/**
 * npm run build         regenerate every template's .html, .txt, groundmail.json and README.md,
 *                       and rewrite the theme regions of the .mjml files from theme.ts
 * npm run build:site    also build the preview site into site/dist
 * npm run check         fail if any generated file is out of date (CI)
 */
import fs from 'node:fs'
import path from 'node:path'
import mjml2html from 'mjml'
import {
  SLUGS,
  interpolate,
  loadTemplate,
  placeholderProps,
  renderHtml,
  sampleVariables,
  toSnake,
  variablesIn,
  type TemplateModule,
} from './registry'
import { applyMjmlRegions } from './mjml-theme'
import { INSTALL, pushSnippets, sendSnippets, type SnippetInput } from './snippets'
import { buildSite } from './site'

const ROOT = path.resolve(import.meta.dirname, '..')
const args = new Set(process.argv.slice(2))
const CHECK = args.has('--check')
const SITE = args.has('--site')

export type BuiltTemplate = {
  slug: string
  name: string
  description: string
  group: string
  subject: string
  variables: Array<{ name: string; prop: string; example: string }>
  sources: { tsx: string; mjml: string; html: string; text: string }
  previews: { react: string; mjml: string }
  sizes: { html: number; mjml: number }
  snippets: { push: ReturnType<typeof pushSnippets>; send: ReturnType<typeof sendSnippets> }
}

const stale: string[] = []

function write(rel: string, content: string) {
  const file = path.join(ROOT, rel)
  const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null
  if (current === content) return
  if (CHECK) {
    stale.push(rel)
    return
  }
  fs.writeFileSync(file, content)
}

function componentNameOf(mod: TemplateModule, slug: string) {
  return mod.default.name || slug.replace(/(^|-)(\w)/g, (_, __, c: string) => c.toUpperCase())
}

function reactPropsSource(preview: Record<string, unknown>): string[] {
  return Object.entries(preview).map(([key, value]) =>
    typeof value === 'string'
      ? `${key}=${JSON.stringify(value)}`
      : `${key}={${JSON.stringify(value, null, 0).replace(/"(\w+)":/g, '$1: ').replace(/,(?=\S)/g, ', ')}}`,
  )
}

function templateReadme(t: BuiltTemplate): string {
  const files = [
    [`${t.slug}.tsx`, 'React Email component. Props are typed; preview with `npm run dev`.'],
    [`${t.slug}.mjml`, 'MJML source. Compiles on its own with `npx mjml`.'],
    [`${t.slug}.html`, 'Ready-to-send HTML with `{{variable}}` placeholders.'],
    [`${t.slug}.txt`, 'Plain-text version with the same placeholders.'],
    ['groundmail.json', 'Template payload for the Groundmail templates API.'],
  ]
  const lang: Record<string, string> = { typescript: 'tsx', bash: 'bash', python: 'python', php: 'php' }
  const send = t.snippets.send
    .map((s) => {
      const install = INSTALL[s.id] ? `\`\`\`bash\n${INSTALL[s.id]}\n\`\`\`\n\n` : ''
      return `### ${s.label}\n\n${install}\`\`\`${lang[s.language] ?? s.language}\n${s.code}\n\`\`\``
    })
    .join('\n\n')
  const push = t.snippets.push
    .map((s) => `**${s.label}**\n\n\`\`\`bash\n${s.code}\n\`\`\``)
    .join('\n\n')

  return `<!-- Generated by \`npm run build\` from ${t.slug}.tsx. Edit that file, not this one. -->

# ${t.name}

${t.description}

- **Subject:** \`${t.subject}\`
- **Live preview:** [groundmail.github.io/email-templates/#${t.slug}](https://groundmail.github.io/email-templates/#${t.slug})

| File | What it is |
|------|------------|
${files.map(([file, what]) => `| [\`${file}\`](${file}) | ${what} |`).join('\n')}

## Variables

| Placeholder | React prop | Example |
|-------------|------------|---------|
${t.variables.map((v) => `| \`{{${v.name}}}\` | \`${v.prop}\` | ${v.example.replace(/\|/g, '\\|')} |`).join('\n')}
${
  t.slug === 'receipt'
    ? `
The HTML, MJML and hosted versions have one line item (\`{{item_description}}\`, \`{{item_amount}}\`). For several items, render the React component in your app (it takes an \`items\` array) or repeat the row in the MJML.
`
    : ''
}
## Create it in your Groundmail account

Each command creates (or updates) a template with the alias \`${t.slug}\` and publishes it. Get an API key with the \`templates:write\` scope at [app.groundmail.dev](https://app.groundmail.dev/signup).

${push}

## Send it with Groundmail

Once the template is in your account, send it by alias and pass the variables. The React Email example skips the hosted template and renders the component at send time.

${send}

---

Using another provider? The \`.html\` and \`.txt\` files use plain \`{{variable}}\` placeholders, which Handlebars, Mustache, Liquid-style engines and most email APIs accept as-is.
`
}

async function buildTemplate(slug: string): Promise<BuiltTemplate> {
  const dir = `templates/${slug}`
  const mod = await loadTemplate(slug)
  const { meta } = mod
  const placeholders = placeholderProps(mod)
  const samples = sampleVariables(mod)

  // HTML + text with {{placeholders}}: what gets stored as an account template.
  const html = await renderHtml(mod, placeholders)
  const text = mod.text(placeholders)
  write(`${dir}/${slug}.html`, html)
  write(`${dir}/${slug}.txt`, text)

  // MJML: refresh the theme/header/footer regions, then compile to check it.
  const mjmlPath = path.join(ROOT, dir, `${slug}.mjml`)
  const mjml = applyMjmlRegions(fs.readFileSync(mjmlPath, 'utf8'))
  write(`${dir}/${slug}.mjml`, mjml)
  const compiled = await mjml2html(mjml, { validationLevel: 'strict', keepComments: false })
  if (compiled.errors.length) {
    throw new Error(`${slug}.mjml: ${compiled.errors.map((e) => e.formattedMessage).join('; ')}`)
  }

  const names = variablesIn(meta.subject, html, text)
  const propByName = new Map<string, string>()
  for (const key of Object.keys(mod.default.PreviewProps)) propByName.set(toSnake(key), key)
  for (const [key, value] of Object.entries(mod.placeholders ?? {})) {
    if (!Array.isArray(value)) continue
    for (const [field, placeholder] of Object.entries(value[0] as Record<string, string>)) {
      const name = /\{\{(\w+)\}\}/.exec(placeholder)?.[1]
      if (name) propByName.set(name, `${key}[].${field}`)
    }
  }
  // Order variables like the component's props, not by first appearance in the HTML.
  const propOrder = Object.keys(mod.default.PreviewProps)
  const rank = (name: string) => propOrder.indexOf((propByName.get(name) ?? name).split('[')[0])
  const variables = names
    .sort((a, b) => rank(a) - rank(b))
    .map((name) => ({ name, prop: propByName.get(name) ?? name, example: samples[name] ?? '' }))

  write(
    `${dir}/groundmail.json`,
    JSON.stringify(
      {
        name: meta.name,
        alias: slug,
        subject: meta.subject,
        format: 'html',
        category: 'transactional',
        html,
        text,
        variables: names,
      },
      null,
      2,
    ) + '\n',
  )

  const input: SnippetInput = {
    slug,
    name: meta.name,
    subject: meta.subject,
    componentName: componentNameOf(mod, slug),
    variables: Object.fromEntries(variables.map((v) => [v.name, v.example])),
    reactProps: reactPropsSource(mod.default.PreviewProps),
  }

  const built: BuiltTemplate = {
    slug,
    name: meta.name,
    description: meta.description,
    group: meta.group,
    subject: meta.subject,
    variables,
    sources: {
      tsx: fs.readFileSync(path.join(ROOT, dir, `${slug}.tsx`), 'utf8'),
      mjml,
      html,
      text,
    },
    previews: {
      // The React preview uses the component's own sample props (the receipt shows several items).
      react: await renderHtml(mod, mod.default.PreviewProps),
      mjml: interpolate(compiled.html, samples, true),
    },
    sizes: { html: Buffer.byteLength(html), mjml: Buffer.byteLength(compiled.html) },
    snippets: { push: pushSnippets(input), send: sendSnippets(input) },
  }
  write(`${dir}/README.md`, templateReadme(built))
  return built
}

export async function buildAll(): Promise<BuiltTemplate[]> {
  const out: BuiltTemplate[] = []
  for (const slug of SLUGS) out.push(await buildTemplate(slug))
  return out
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === path.resolve(import.meta.filename)
if (isMain) {
  const built = await buildAll()
  if (CHECK && stale.length) {
    console.error(`Generated files are out of date. Run \`npm run build\` and commit:\n  ${stale.join('\n  ')}`)
    process.exit(1)
  }
  if (SITE) await buildSite(built, path.join(ROOT, 'site', 'dist'))
  console.log(
    built.map((t) => `${t.slug.padEnd(22)} html ${(t.sizes.html / 1024).toFixed(1)} KB  mjml ${(t.sizes.mjml / 1024).toFixed(1)} KB`).join('\n'),
  )
}
